import com.auth0.jwt.JWT;
import com.auth0.jwt.interfaces.DecodedJWT;
import org.junit.Test;

import java.time.Instant;
import java.util.Base64;
import java.util.Date;

import static org.junit.Assert.*;

public class TestSweDuelFeature {

    private String createToken(String payloadJson) {
        String header = Base64.getUrlEncoder().withoutPadding().encodeToString("{\"alg\":\"HS256\"}".getBytes());
        String payload = Base64.getUrlEncoder().withoutPadding().encodeToString(payloadJson.getBytes());
        return header + "." + payload + ".signature";
    }

    // Test isExpired() and isExpired(Instant)
    @Test
    public void testIsExpired() {
        // Token with exp claim in the past (expired)
        String expiredToken = createToken("{\"exp\":1000000000}");
        DecodedJWT jwt = JWT.decode(expiredToken);
        assertTrue("Token with past exp should be expired", jwt.isExpired());
        assertTrue("Token with past exp should be expired at specific time", jwt.isExpired(Instant.now()));

        // Token with exp claim in the future (not expired)
        long futureExp = Instant.now().plusSeconds(3600).getEpochSecond();
        String futureToken = createToken("{\"exp\":" + futureExp + "}");
        DecodedJWT futureJwt = JWT.decode(futureToken);
        assertFalse("Token with future exp should not be expired", futureJwt.isExpired());
        assertFalse("Token with future exp should not be expired at specific time", futureJwt.isExpired(Instant.now()));

        // Token without exp claim (not expired)
        String noExpToken = createToken("{\"sub\":\"test\"}");
        DecodedJWT noExpJwt = JWT.decode(noExpToken);
        assertFalse("Token without exp claim should not be expired", noExpJwt.isExpired());
        assertFalse("Token without exp claim should not be expired at specific time", noExpJwt.isExpired(Instant.now()));
    }

    // Test isNotBefore() and isNotBefore(Instant)
    @Test
    public void testIsNotBefore() {
        // Token with nbf claim in the future (not yet valid)
        long futureNbf = Instant.now().plusSeconds(3600).getEpochSecond();
        String futureNbfToken = createToken("{\"nbf\":" + futureNbf + "}");
        DecodedJWT futureNbfJwt = JWT.decode(futureNbfToken);
        assertTrue("Token with future nbf should be not before now", futureNbfJwt.isNotBefore());
        assertTrue("Token with future nbf should be not before at specific time", futureNbfJwt.isNotBefore(Instant.now()));

        // Token with nbf claim in the past (valid)
        String pastNbfToken = createToken("{\"nbf\":1000000000}");
        DecodedJWT pastNbfJwt = JWT.decode(pastNbfToken);
        assertFalse("Token with past nbf should not be not before now", pastNbfJwt.isNotBefore());
        assertFalse("Token with past nbf should not be not before at specific time", pastNbfJwt.isNotBefore(Instant.now()));

        // Token without nbf claim (valid)
        String noNbfToken = createToken("{\"sub\":\"test\"}");
        DecodedJWT noNbfJwt = JWT.decode(noNbfToken);
        assertFalse("Token without nbf claim should not be not before now", noNbfJwt.isNotBefore());
        assertFalse("Token without nbf claim should not be not before at specific time", noNbfJwt.isNotBefore(Instant.now()));
    }

    // Test isValid() and isValid(Instant)
    @Test
    public void testIsValid() {
        // Token with both exp in future and nbf in past (valid)
        long futureExp = Instant.now().plusSeconds(3600).getEpochSecond();
        long pastNbf = Instant.now().minusSeconds(3600).getEpochSecond();
        String validToken = createToken("{\"exp\":" + futureExp + ",\"nbf\":" + pastNbf + "}");
        DecodedJWT validJwt = JWT.decode(validToken);
        assertTrue("Token with future exp and past nbf should be valid", validJwt.isValid());
        assertTrue("Token with future exp and past nbf should be valid at specific time", validJwt.isValid(Instant.now()));

        // Token with exp in past (expired, not valid)
        String expiredToken = createToken("{\"exp\":1000000000}");
        DecodedJWT expiredJwt = JWT.decode(expiredToken);
        assertFalse("Token with past exp should not be valid", expiredJwt.isValid());
        assertFalse("Token with past exp should not be valid at specific time", expiredJwt.isValid(Instant.now()));

        // Token with nbf in future (not yet valid)
        long futureNbf = Instant.now().plusSeconds(3600).getEpochSecond();
        String notYetValidToken = createToken("{\"nbf\":" + futureNbf + "}");
        DecodedJWT notYetValidJwt = JWT.decode(notYetValidToken);
        assertFalse("Token with future nbf should not be valid", notYetValidJwt.isValid());
        assertFalse("Token with future nbf should not be valid at specific time", notYetValidJwt.isValid(Instant.now()));

        // Token with both exp in past and nbf in future (not valid)
        String bothInvalidToken = createToken("{\"exp\":1000000000,\"nbf\":9999999999}");
        DecodedJWT bothInvalidJwt = JWT.decode(bothInvalidToken);
        assertFalse("Token with past exp and future nbf should not be valid", bothInvalidJwt.isValid());
        assertFalse("Token with past exp and future nbf should not be valid at specific time", bothInvalidJwt.isValid(Instant.now()));

        // Token without exp and nbf claims (valid)
        String noClaimsToken = createToken("{\"sub\":\"test\"}");
        DecodedJWT noClaimsJwt = JWT.decode(noClaimsToken);
        assertTrue("Token without exp and nbf should be valid", noClaimsJwt.isValid());
        assertTrue("Token without exp and nbf should be valid at specific time", noClaimsJwt.isValid(Instant.now()));
    }

    // Test edge cases with specific time parameter
    @Test
    public void testValidityAtSpecificTime() {
        // Token expiring at a specific time (2024-01-01T00:00:00Z = 1704067200)
        String token = createToken("{\"exp\":1704067200}");
        DecodedJWT jwt = JWT.decode(token);

        // Before expiration - should be valid
        Instant beforeExp = Instant.parse("2023-12-31T23:59:59Z");
        assertFalse("Token should not be expired before exp time", jwt.isExpired(beforeExp));
        assertTrue("Token should be valid before exp time", jwt.isValid(beforeExp));

        // At expiration - should be expired (isExpired uses isAfter, so at exact time it's not expired)
        Instant atExp = Instant.parse("2024-01-01T00:00:00Z");
        assertFalse("Token should not be expired at exact exp time (isAfter)", jwt.isExpired(atExp));
        assertTrue("Token should be valid at exact exp time", jwt.isValid(atExp));

        // After expiration - should be expired
        Instant afterExp = Instant.parse("2024-01-01T00:00:01Z");
        assertTrue("Token should be expired after exp time", jwt.isExpired(afterExp));
        assertFalse("Token should not be valid after exp time", jwt.isValid(afterExp));

        // Test nbf at specific time (2024-01-01T00:00:00Z = 1704067200)
        String nbfToken = createToken("{\"nbf\":1704067200}");
        DecodedJWT nbfJwt = JWT.decode(nbfToken);

        // Before nbf - should be not before
        Instant beforeNbf = Instant.parse("2023-12-31T23:59:59Z");
        assertTrue("Token should be not before before nbf time", nbfJwt.isNotBefore(beforeNbf));
        assertFalse("Token should not be valid before nbf time", nbfJwt.isValid(beforeNbf));

        // At nbf - should be valid (isNotBefore uses isBefore, so at exact time it's not not-before)
        Instant atNbf = Instant.parse("2024-01-01T00:00:00Z");
        assertFalse("Token should not be not before at exact nbf time (isBefore)", nbfJwt.isNotBefore(atNbf));
        assertTrue("Token should be valid at exact nbf time", nbfJwt.isValid(atNbf));

        // After nbf - should be valid
        Instant afterNbf = Instant.parse("2024-01-01T00:00:01Z");
        assertFalse("Token should not be not before after nbf time", nbfJwt.isNotBefore(afterNbf));
        assertTrue("Token should be valid after nbf time", nbfJwt.isValid(afterNbf));
    }

    // Test null time parameter throws exception
    @Test(expected = IllegalArgumentException.class)
    public void testIsExpiredWithNullTime() {
        String token = createToken("{\"exp\":1000000000}");
        DecodedJWT jwt = JWT.decode(token);
        jwt.isExpired((Instant) null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIsNotBeforeWithNullTime() {
        String token = createToken("{\"nbf\":1000000000}");
        DecodedJWT jwt = JWT.decode(token);
        jwt.isNotBefore((Instant) null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIsValidWithNullTime() {
        String token = createToken("{\"sub\":\"test\"}");
        DecodedJWT jwt = JWT.decode(token);
        jwt.isValid((Instant) null);
    }
}

