import com.auth0.jwt.JWT;
import com.auth0.jwt.interfaces.DecodedJWT;
import org.junit.Test;

import java.time.Instant;
import java.util.Base64;

import static org.junit.Assert.*;

public class TestSweDuelBug {

    private String createToken(String payloadJson) {
        String header = Base64.getUrlEncoder().withoutPadding().encodeToString("{\"alg\":\"HS256\"}".getBytes());
        String payload = Base64.getUrlEncoder().withoutPadding().encodeToString(payloadJson.getBytes());
        return header + "." + payload + ".signature";
    }

    // Test that isValid(Instant) correctly uses the provided time for BOTH exp and nbf checks
    // This tests for a bug where isValid(Instant) might use Instant.now() for the nbf check
    @Test
    public void testIsValidAtSpecificTimeWithBothExpAndNbf() {
        // Create a token with both exp in the future and nbf in the past (relative to a specific test time)
        // Test time: 2024-01-01T12:00:00Z (1704110400)
        // exp: 2024-01-01T13:00:00Z (1704114000) - 1 hour in the future from test time
        // nbf: 2024-01-01T11:00:00Z (1704106800) - 1 hour in the past from test time
        long exp = 1704114000L; // 2024-01-01T13:00:00Z
        long nbf = 1704106800L; // 2024-01-01T11:00:00Z
        String token = createToken("{\"exp\":" + exp + ",\"nbf\":" + nbf + "}");
        DecodedJWT jwt = JWT.decode(token);

        // Test time: 2024-01-01T12:00:00Z - token should be valid (not expired, not before nbf)
        Instant testTime = Instant.parse("2024-01-01T12:00:00Z");
        assertTrue("Token should be valid at test time (exp in future, nbf in past)", jwt.isValid(testTime));

        // Test time: 2024-01-01T10:00:00Z - token should NOT be valid (before nbf)
        Instant beforeNbf = Instant.parse("2024-01-01T10:00:00Z");
        assertFalse("Token should not be valid before nbf", jwt.isValid(beforeNbf));

        // Test time: 2024-01-01T14:00:00Z - token should NOT be valid (after exp)
        Instant afterExp = Instant.parse("2024-01-01T14:00:00Z");
        assertFalse("Token should not be valid after exp", jwt.isValid(afterExp));
    }

    // Test that isValid(Instant) correctly uses the provided time when nbf is in the future relative to now
    // but in the past relative to the test time
    @Test
    public void testIsValidAtSpecificTimeNbfInFutureRelativeToNow() {
        // Current time is roughly "now" when test runs
        // Create a token with nbf in the future relative to now, but we'll test at a time after nbf
        long futureNbf = Instant.now().plusSeconds(7200).getEpochSecond(); // 2 hours in future
        long futureExp = Instant.now().plusSeconds(10800).getEpochSecond(); // 3 hours in future
        String token = createToken("{\"exp\":" + futureExp + ",\"nbf\":" + futureNbf + "}");
        DecodedJWT jwt = JWT.decode(token);

        // Test at a time that is AFTER the nbf (so token should be valid if nbf check uses test time)
        // but BEFORE the nbf relative to now (so token would be invalid if nbf check uses now)
        Instant testTime = Instant.ofEpochSecond(futureNbf + 3600); // 1 hour after nbf

        // The token should be valid at testTime because testTime is after nbf and before exp
        // BUG: If isValid(Instant) uses Instant.now() for nbf check, it would return false
        // because now is before nbf
        assertTrue("Token should be valid at testTime (after nbf, before exp)", jwt.isValid(testTime));
    }
}

